// The validation gate, equivalent to models.py.
// Anything that fails here is routed to the dead letter, never stored.
const allowed = ['youtube', 'tiktok', 'instagram'];
const out = [];

for (const item of $input.all()) {
  const a = item.json;
  const errors = [];

  if (!a.external_id) errors.push('external_id is required');
  if (!a.email || !a.email.includes('@')) errors.push('email is not valid');
  if (!Number.isInteger(a.followers) || a.followers < 0) errors.push('followers must be a non-negative integer');

  const platform = String(a.platform || '').trim().toLowerCase();
  if (!allowed.includes(platform)) errors.push(`unsupported platform ${platform}`);

  const handle = String(a.handle || '').trim().replace(/^@/, '');

  if (errors.length) {
    out.push({ json: { ...a, _valid: false, _error: errors.join('; ') } });
    continue;
  }

  // Derived, not random: the same applicant always gets the same code, so a
  // replay cannot produce a second creator. See steps/onboard.py.
  const crypto = require('crypto');
  const digest = crypto.createHash('sha1').update(a.external_id).digest('hex').slice(0, 8).toUpperCase();

  out.push({ json: { ...a, platform, handle, _valid: true, tracking_code: `CP-${digest}` } });
}

return out;
